#include "CloseToHSL/Core/Virtualization/Compatibility/Frontend/Retire/VmxRetireModel.h"
#include "CloseToHSL/Core/Virtualization/Compatibility/Frontend/Projection/Events/TrapDecision.h"
#include "CloseToHSL/Core/Runtime/Completion/Records/TrapCompletionPublicationFence.h"
#include <cassert>
using namespace YAKSys_Hybrid_CPU::Core;
int main(){ VmxRetireEffect empty; assert(!empty.isValid()); auto fault=VmxRetireEffect::Fault(VmxOperationKind::VmRead,VmExitReason::SecurityPolicyViolation); assert(fault.isFaulted() && fault.getCompletionKind()==VmxCompletionKind::VmFailInvalid && fault.getRootDescriptor()->IsLegacyDefault); auto call=VmxRetireEffect::VmCall(7,42,true); assert(call.getExitGuestContextOnRetire() && call.getCompletionKind()==VmxCompletionKind::VmExit && call.getExitQualification()->Encode()==(42ULL<<32|7)); auto invalid=VmxRetireEffect::Invalidation(VmxOperationKind::Invept,VmxInvalidationScope::AllContexts,5); assert(invalid.getInvalidationScope()==VmxInvalidationScope::AllContexts && invalid.getExitQualification()->Encode()==(5ULL<<32|2ULL<<16)); auto rec=std::make_shared<CompletionRecord>(CompletionRecordClass::Trap,1,0,0,0); auto allowed=std::make_shared<TrapCompletionPublicationFenceResult>(TrapCompletionPublicationDecision::Allowed,nullptr,rec,true,L""); auto denied=std::make_shared<TrapCompletionPublicationFenceResult>(TrapCompletionPublicationDecision::DeniedBackendExecution,nullptr,CompletionRecord::getNone(),false,L""); auto decision=TrapDecision::Exit(TrapRequest::ForInstruction(1,0),VmExitReason::InstructionIntercept); assert(!VmxRetireEffect::InterceptExit(decision,allowed).isFaulted()); assert(VmxRetireEffect::InterceptExit(decision,denied).isFaulted()); }
